-- Fields the Work Authorization and Proposal layouts need, and the standard Minol wording as editable clauses.
ALTER TABLE property
  ADD COLUMN city text,
  ADD COLUMN state text,
  ADD COLUMN zip text;

ALTER TABLE document
  ADD COLUMN addressee text,                   -- Proposal "Submitted to" block, one line per row
  ADD COLUMN notes text,                       -- scope notes printed under the items
  ADD COLUMN shipping numeric(10,2),           -- Proposal estimated shipping & handling
  ADD COLUMN prepared_by text;                 -- initials; defaults to the creator's initials

ALTER TABLE app_user ADD COLUMN initials text;

-- The layout places these by key (wa_intro, wa_estimate, quote_notice, quote_expiry, wa_authorization, proposal_acceptance, resident_notice).
INSERT INTO clause_template (key,title,body,applies_when) VALUES
('wa_intro','Why this authorization','As with any electronic system, parts can fail or a system can become inoperative due to unforeseen circumstances (phone line issues, resident tampering, wiring problems, etc). The Minol Meter Reading and Service Department has detected problems with your system in need of service. Since regulations limit the period in which resident submeters can be estimated, immediate service is crucial.','{"types":["WA"]}'),
('wa_estimate','How the estimate works','Please find below an estimated cost of service. You will be billed for the actual work that needs to be done. Service cost is associated to the degree of failure and is based upon quantity and type of replacement parts needed and the amount of labor. Since this cannot be determined until a qualified technician checks the equipment on-site, we have attempted to give you the most accurate diagnostic based on the meter reading data we have collected. You will only be invoiced for actual equipment & labor used. In addition, we have included a list of applicable buildings and/or units which have been affected. Pricing includes costs associated with installing transmitters on meters installed at a reasonable installation height accessible by a 6 foot A-Frame ladder. Client is responsible for providing the means to safely access any and all locations.','{"types":["WA"],"audience":"client"}'),
('quote_notice','Important notification','This statement is a quote for work to be completed and not an invoice. Work will be invoiced monthly as it is completed. In the event that any invoices are not paid by their due date a late penalty in the amount of 1.5% per month (18% per annum) will be applied to any unpaid or past due amounts. If client utilizes vendor verification, payment processing, or other services that impose fees upon Minol, they will be borne by the Client. Minol reserves the right to recoup these costs.','{"types":["WA","Proposal"],"audience":"client"}'),
('quote_expiry','Quote validity','This quotation by Minol shall expire automatically thirty (30) days after the date on this document. Prior to the expiration date, any quotation is subject to change by Minol at any time upon written notice to Buyer unless Minol receives and accepts Buyer''s order within the aforementioned validity period.','{"types":["WA","Proposal"],"audience":"client"}'),
('wa_authorization','Owner service work authorization','Please initial one option below, sign and return to Minol via email at ServiceWA@minolusa.com to prevent any delays in scheduling. Work will not be scheduled until a signed authorization is received by the Minol Service Department.
I authorize MINOL to provide a technician to evaluate and complete all necessary utility submetering system repairs. I understand that if the equipment is no longer under Warranty or work is not covered by Extended Warranty, then all repair costs are the responsibility of the owner. I also understand that it is the responsibility of the property owner to send resident written notices prior to the technician''s arrival. Please see attached page for a list of applicable units.
I DO NOT authorize Minol to complete repairs at this time. I understand that I have been notified and that the property owner is responsible for any resident billing interruptions or delays attributed to equipment failure.
I understand that if the Minol technician cannot complete the work due to property issues (key, residents, etc.) then the property will be charged for all labor costs.','{"types":["WA"],"audience":"client"}'),
('proposal_acceptance','Acceptance of proposal','Minol, Inc offers to sell the goods and services described above only upon the terms and conditions contained in this entire Meter Service Work Authorization Proposal. Minol, Inc reserves the right to revoke this offer without notice. This offer shall be deemed accepted and shall become a binding contract on the terms and conditions contained herein when signed or email provided stating approval accepted. Pricing includes costs associated with installing transmitters on meters installed at a reasonable installation height accessible by a 6 foot A-Frame ladder. Client is responsible for providing the means to safely access any and all locations that would not be accessible with a standard 6 foot A-Frame ladder.','{"types":["Proposal"],"audience":"client"}'),
('resident_notice','Resident access notice','This letter serves as a 48-hour notice to you that a representative from Minol will be accessing your apartment in order to complete repairs on the automated sub-metering equipment located in your apartment. Please make any necessary arrangements to have pets secured or relocated from the area where the technician will be working.
Please be aware that if you fail to allow access for the above scheduled service, repairs will not be completed and you acknowledge that future meter readings associated to your utility consumption may be estimated until service can be rescheduled. Your presence for service is optional.
We appreciate your cooperation and look forward to providing you with exceptional service. Please note that Minol Technicians wear identification badges. In addition, you may also contact the Management Office if you should have any questions.','{"types":["WA"],"audience":"client"}');
